"""Source/criterion validation; TA display facts are generated by the backend."""

import re
from decimal import Decimal

from pydantic import ValidationError

from app.domains.scoring.essay_sources import SourceSegment
from app.domains.scoring.task1_facts import DerivedFact
from app.domains.scoring.task2_explanations import ExplanationIssues
from app.domains.scoring.task2_feedback import (
    normalize_task2_feedback,
    render_task2_feedback,
    select_feedback_observations,
)
from app.schemas.task1_claims import Task1Analysis
from app.schemas.task1_feedback import (
    RawTask1FeedbackDraft,
    RawTask1FeedbackObservation,
    Task1LanguageFeedbackVerification,
)
from app.schemas.task1_visual import ChartTableVisualReference
from app.schemas.writing_ai import RawTask2FeedbackDraft, Task2FeedbackDraft, Trait

_ASPECTS = {
    "ta": {
        "overview",
        "key_feature",
        "comparison",
        "factual_accuracy",
        "omission",
        "task_fulfilment",
    },
    "cc": {"progression", "grouping", "paragraphing", "sequencing", "cohesion", "reference"},
    "lr": {"range", "precision", "collocation", "spelling", "word_formation", "style"},
    "gra": {"grammar", "sentence_structure", "punctuation", "range", "style"},
}
_COHESION_ADVICE = re.compile(
    r"discourse markers?|linking words?|conceptual transitions?|cohesion|"
    r"logical links?|connect.{0,30}logically|chuyển ý|mạch lạc|liên kết ý|thêm từ nối",
    re.I,
)
_VARIETY_ADVICE = re.compile(
    r"synonym.{0,80}(variety|variation)|merely for.{0,20}(variety|variation)|"
    r"đồng nghĩa.{0,80}(đa dạng|phong phú)|(?:đa dạng|phong phú).{0,80}đồng nghĩa",
    re.I,
)
_CONNECTOR_QUOTA = re.compile(
    r"connector.{0,40}every (sentence|paragraph)|linker.{0,40}every (sentence|paragraph)|"
    r"(?:từ nối|liên từ).{0,40}(?:mỗi câu|mỗi đoạn)",
    re.I,
)


def _fact_text(fact: DerivedFact) -> str:
    names = ", ".join(fact.subjects)
    period = fact.category or ""
    if fact.end_category:
        period += f" → {fact.end_category}"
    kinds = {
        "value": "giá trị",
        "absolute_change": "mức thay đổi",
        "percentage_change": "thay đổi tương đối (%)",
        "rank": "thứ hạng",
        "rank_change": "thay đổi thứ hạng",
        "min": "giá trị nhỏ nhất",
        "max": "giá trị lớn nhất",
        "start": "giá trị đầu",
        "end": "giá trị cuối",
        "largest_increase": "mức tăng lớn nhất",
        "largest_decrease": "mức giảm lớn nhất",
    }
    if fact.value is not None:
        detail = f"{kinds.get(fact.kind, 'giá trị')} {format(fact.value, 'f')}"
    else:
        detail = {"increase": "tăng", "decrease": "giảm", "stable": "không thay đổi"}.get(
            fact.direction, ""
        )
    return f"{names} ({period}): {detail}" if detail else ""


def _ta_text(item, analysis, source):
    # Extraction is not exhaustive: neither absence from the selected evidence
    # nor absence from the claim list establishes a material omission.
    if (
        item.aspect == "omission"
        or item.observation is not None
        or item.suggested_revision is not None
    ):
        return None
    if analysis.confidence not in {"HIGH", "MEDIUM"}:
        return None
    claim = next((c for c in analysis.claims if c.claim_id == item.claim_id), None)
    if claim is None or source.source_id not in claim.source_ids:
        return None
    if item.kind == "STRENGTH" and claim.verdict == "SUPPORTED":
        return "Trích dẫn này trình bày nội dung đã được đối chiếu là phù hợp với hình."
    if (
        item.kind != "ERROR"
        or item.aspect != "factual_accuracy"
        or claim.verdict != "CONTRADICTED"
        or not item.original_span
        or item.original_span not in source.text
        or item.original_span not in claim.quote
    ):
        return None
    facts = {fact.id: fact for fact in analysis.derived_facts}
    if not claim.evidence or any(identity not in facts for identity in claim.evidence):
        return None
    truth = [_fact_text(facts[identity]) for identity in claim.evidence]
    if not all(truth):
        return None
    return "Đối chiếu lại nội dung trong trích dẫn. Dữ liệu từ hình: " + "; ".join(truth) + "."


def _fixed_labels(analysis):
    if not isinstance(analysis.reference, ChartTableVisualReference):
        return set()
    return {
        label.casefold().strip()
        for component in analysis.reference.components
        for label in [
            *component.categories,
            *component.row_headers,
            *component.column_headers,
            *(series.name for series in component.series),
        ]
    }


def normalize_task1_feedback(
    draft: RawTask1FeedbackDraft,
    sources: dict[str, SourceSegment],
    trait: Trait,
    score: Decimal,
    analysis: Task1Analysis,
) -> tuple[Task2FeedbackDraft, ExplanationIssues]:
    issues = ExplanationIssues()
    accepted = []
    labels = _fixed_labels(analysis)
    for index, value in enumerate(draft.observations):
        prefix = f"observations.{index}"
        try:
            item = RawTask1FeedbackObservation.model_validate(value)
        except ValidationError as error:
            issues.invalid_item(prefix, error)
            continue
        source = sources.get(item.source_id)
        if source is None:
            issues.drop(f"{prefix}.source_id")
            continue
        if item.aspect not in _ASPECTS[trait] or (
            item.aspect == "style" and item.kind != "OPTIONAL_REFINEMENT"
        ):
            issues.drop(f"{prefix}.aspect")
            continue
        text = item.observation
        if trait == "ta":
            text = _ta_text(item, analysis, source)
        if text is None:
            issues.drop(f"{prefix}.observation")
            continue
        prose = f"{text} {item.suggested_revision or ''}"
        # Keep linguistic inference independent of perception. If grounding has
        # not finished, do not guess whether a lexical rewrite targets a label.
        if trait == "lr" and item.suggested_revision and analysis.reference is None:
            issues.drop(f"{prefix}.suggested_revision")
            continue
        if item.kind != "STRENGTH" and (
            (trait == "gra" and _COHESION_ADVICE.search(prose))
            or (
                trait == "lr"
                and (
                    _VARIETY_ADVICE.search(prose)
                    or (
                        item.suggested_revision
                        and item.original_span
                        and item.original_span.casefold().strip() in labels
                    )
                )
            )
            or (trait == "cc" and _CONNECTOR_QUOTA.search(prose))
        ):
            issues.drop(f"{prefix}.aspect")
            continue
        raw = item.model_dump(exclude={"aspect", "claim_id"})
        raw["observation"] = text
        normalized, local = normalize_task2_feedback(
            RawTask2FeedbackDraft(observations=[raw]), sources, trait, score
        )
        # Remap the shared sanitizer's safe item paths to this candidate's index.
        for group in ("normalized", "dropped"):
            for issue in getattr(local, group):
                issue.field = issue.field.replace("observations.0", prefix, 1)
                getattr(issues, group).append(issue)
        for candidate in normalized.observations:
            if candidate not in accepted:
                accepted.append(candidate)
    return Task2FeedbackDraft(observations=select_feedback_observations(accepted, sources)), issues


def apply_language_verification(
    draft: Task2FeedbackDraft, verification: Task1LanguageFeedbackVerification
) -> Task2FeedbackDraft:
    candidates = {
        index: item
        for index, item in enumerate(draft.observations)
        if item.kind in {"ERROR", "LIMITATION"}
    }
    decisions = {item.observation_index: item for item in verification.decisions}
    if len(decisions) != len(verification.decisions) or decisions.keys() != candidates.keys():
        raise ValueError("Incomplete language verification decisions")
    for index, decision in decisions.items():
        expected = (
            "CLEAR_LANGUAGE_ERROR"
            if candidates[index].kind == "ERROR"
            else "MATERIAL_RECURRENT_LIMITATION"
        )
        if decision.accept and decision.reason_code != expected:
            raise ValueError("Language verification kind mismatch")
    return draft.model_copy(
        update={
            "observations": [
                item
                for index, item in enumerate(draft.observations)
                if index not in candidates or decisions[index].accept
            ]
        }
    )


def render_task1_feedback(draft, sources):
    # Style alternatives are not Task 1 mistakes, summary evidence or Fix next.
    public = draft.model_copy(
        update={
            "observations": [
                item for item in draft.observations if item.kind != "OPTIONAL_REFINEMENT"
            ]
        }
    )
    return render_task2_feedback(public, sources)
